BEFORE INSERT ON feedbacks
FOR EACH ROW EXECUTE FUNCTION v27_require_existing_references();

-- 1. Seed payment transactions (SePay)
-- Resolve plans by their stable business key because plan UUIDs differ between environments.

-- 2. Seed platform treasury entries

-- 3. Synchronize subscriptions from the V27 paid payment batch.
-- A paid payment inserted directly by Flyway does not execute
-- SubscriptionService.activatePaidPlan(), so derive the current subscription state
-- from the payment history here. The batch-specific txn_ref prefix prevents this
-- migration from rewriting subscriptions that are unrelated to the V27 seed.
CREATE TEMP TABLE v27_paid_subscription_sync ON COMMIT DROP AS
WITH scoped_payments AS (
    SELECT payment.*
    FROM payment_transactions payment
    WHERE payment.status = 'PAID'
      AND payment.purpose = 'SUBSCRIPTION'
      AND payment.txn_ref LIKE 'DH178504436%'
      AND NOT EXISTS (
          SELECT 1
          FROM subscriptions admin_subscription
          JOIN service_plans admin_plan
            ON admin_plan.plan_id = admin_subscription.plan_id
          WHERE admin_subscription.user_id = payment.user_id
            AND admin_subscription.status = 'ACTIVE'
            AND admin_plan.plan_type = 'ADMIN_DEFAULT'
      )
),
payment_periods AS (
    SELECT
        payment.user_id,
        MIN(payment.paid_at) AS start_at,
        MAX(payment.paid_at) AS latest_paid_at,
        SUM(payment.subscription_months)::integer AS purchased_months
    FROM scoped_payments payment
    GROUP BY payment.user_id
),
latest_paid_plans AS (
    SELECT DISTINCT ON (payment.user_id)
        payment.user_id,
        payment.plan_id,
        payment.subscription_months::integer AS latest_payment_months
    FROM scoped_payments payment
    ORDER BY payment.user_id, payment.paid_at DESC, payment.payment_id DESC
),
paid_states AS (
    SELECT
        period.user_id,
        latest_plan.plan_id,
        period.start_at,
        GREATEST(
            period.latest_paid_at + make_interval(months => latest_plan.latest_payment_months),
            period.start_at + make_interval(months => period.purchased_months)
        ) AS end_at
    FROM payment_periods period
    JOIN latest_paid_plans latest_plan
      ON latest_plan.user_id = period.user_id
),
current_subscription_targets AS (
    SELECT DISTINCT ON (subscription.user_id)
        subscription.user_id,
        subscription.subscription_id
    FROM subscriptions subscription
    JOIN paid_states paid_state
      ON paid_state.user_id = subscription.user_id
    ORDER BY
        subscription.user_id,
        CASE WHEN subscription.status = 'ACTIVE' THEN 0 ELSE 1 END,
        subscription.created_at DESC,
        subscription.subscription_id
)
SELECT
    paid_state.user_id,
    COALESCE(target.subscription_id, gen_random_uuid()) AS subscription_id,
    paid_state.plan_id,
    paid_state.start_at,
    paid_state.end_at,
    CASE
        WHEN paid_state.end_at > CURRENT_TIMESTAMP THEN 'ACTIVE'
        ELSE 'EXPIRED'
    END AS status
FROM paid_states paid_state
LEFT JOIN current_subscription_targets target
  ON target.user_id = paid_state.user_id;

-- Ensure getCurrentPlan() sees at most one active subscription per seeded user.
UPDATE subscriptions subscription
SET
    status = 'CANCELED',
    end_at = LEAST(
        COALESCE(subscription.end_at, sync.start_at),
        sync.start_at
    ),
    end_date = (
        LEAST(
            COALESCE(subscription.end_at, sync.start_at),
            sync.start_at
        ) AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )::date
FROM v27_paid_subscription_sync sync
WHERE subscription.user_id = sync.user_id
  AND subscription.subscription_id <> sync.subscription_id
  AND subscription.status = 'ACTIVE';

-- Reuse the user's current/latest subscription when it already exists.
UPDATE subscriptions subscription
SET
    plan_id = sync.plan_id,
    start_at = sync.start_at,
    end_at = sync.end_at,
    start_date = (sync.start_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    end_date = (sync.end_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    status = sync.status
FROM v27_paid_subscription_sync sync
WHERE subscription.subscription_id = sync.subscription_id;

-- A user without a subscription still receives one for the paid payment history.
    subscription_id,
    user_id,
    plan_id,
    start_date,
    end_date,
    start_at,
    end_at,
    status,
    created_at
)
SELECT
    sync.subscription_id,
    sync.user_id,
    sync.plan_id,
    (sync.start_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    (sync.end_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    sync.start_at,
    sync.end_at,
    sync.status,
    sync.start_at
FROM v27_paid_subscription_sync sync
WHERE NOT EXISTS (
    SELECT 1
    FROM subscriptions subscription
    WHERE subscription.subscription_id = sync.subscription_id
);

DROP TABLE v27_paid_subscription_sync;

