INSERT INTO feedbacks (feedback_id, created_at, updated_at, title, type, content, status, user_id, admin_reply, replied_at, replied_by_user_id) VALUES ('855778be-8178-4a1a-816f-863366a3be19', '2026-06-17T03:56:04.523Z', '2026-06-17T03:56:04.523Z', 'Gợi ý thêm giao diện Dark Mode cho phần Pomodoro', 'IMPROVEMENT', 'Mình thấy giao diện học tập ban đêm hơi sáng, nếu có thêm chế độ Dark Mode cho Pomodoro thì tuyệt vời hơn ạ.', 'RESOLVED', '1a750521-8c2e-4fcc-a1b1-805b8e27391c', 'Cảm ơn đóng góp của bạn! Đội ngũ phát triển đã ghi nhận và đang triển khai Dark Mode trong bản cập nhật sắp tới.', '2026-06-18T03:56:04.523Z', '02e36a78-0ad6-4777-b173-778aa984022c') ON CONFLICT (feedback_id) DO NOTHING;
